fastify.setErrorHandler((error, request, reply) => {
  request.log.error(error)
  reply.code(error.statusCode || 500).send({ error: error.message })
})

const err = new Error('Not found')
err.statusCode = 404
throw err

class NotFoundError extends Error {
  constructor(msg) {
    super(msg)
    this.statusCode = 404
  }
}
